mapper.select:
SELECT * FROM memory_tags
WHERE user_id = #{userId} AND deleted = 0 AND anchor_embedding IS NOT NULL
  AND (anchor_embedding <=> #{queryVec}::halfvec) <= #{threshold}
ORDER BY anchor_embedding <=> #{queryVec}::halfvec
LIMIT #{limit}

SELECT t.id, t.subject, t.topic, t.label, t.user_id AS owner_user_id, t.usage_count
FROM memory_tags t
WHERE t.deleted = 0
  AND t.id IN (
      SELECT unnest(tag_ids) FROM memory_turns
      WHERE deleted = 0 AND gen_done = true
        AND user_id = #{userId}
         AND direction = #{direction} 
         AND created_at >= NOW() - make_interval(days => #{relativeDays}) 
         AND created_at >= #{twStart} 
         AND created_at <= #{twEnd} 
      UNION
      SELECT tag_id FROM memory_summaries
      WHERE deleted = 0 AND status != 'STALE'
        AND user_id = #{userId} AND project_id IS NULL
         AND summarized_at >= NOW() - make_interval(days => #{relativeDays}) 
         AND summarized_at >= #{twStart} 
         AND summarized_at <= #{twEnd} 
  )
ORDER BY t.usage_count DESC

SELECT id FROM memory_tags
WHERE deleted = 0 AND anchor_embedding IS NOT NULL
  AND id IN

      #{tid}

ORDER BY anchor_embedding <=> #{queryVec}::halfvec
LIMIT #{limit}

SELECT id FROM memory_tags WHERE deleted = 0 AND id IN
#{tid}
AND anchor_tokens_tsv @@ plainto_tsquery('simple', #{queryTokens}) ORDER BY ts_rank(anchor_tokens_tsv, plainto_tsquery('simple', #{queryTokens})) DESC LIMIT #{limit}
